"737 :   static boolean isSimpleNumber(String s) {
738 :     int len = s.length();
739 :     for (int index = 0; index < len; index++) {
740 :       char c = s.charAt(index);
741 :       if (c < '0' || c > '9') {
742 :         return false;
743 :       }
744 :     }
745 :     return len > 0;
746 :   }"

m15.content:
"748 :   static double getSimpleNumber(String s) {
749 :     if (isSimpleNumber(s)) {
750 :       try {
751 :         long l = Long.parseLong(s);
752 :         if (l < NodeUtil.MAX_POSITIVE_INTEGER_NUMBER) {
753 :           return l;
754 :         }
755 :       } catch (NumberFormatException e) {
756 :         // The number was too long to parse. Fall through to NaN.
757 :       }
758 :     }
759 :     return Double.NaN;
760 :   }"
